function ev(nm,p){try{window.dataLayer=window.dataLayer||[];var o={event:'ck_'+nm};if(p)for(var kk in p)o[kk]=p[kk];window.dataLayer.push(o);}catch(e){}}
/* ---- KOSZYK: /api/basket storefrontu; bierze STOCK_ID, nie product_id ---- */

var CK_LS_ID='BasketLocalStore.basketId',CK_LS_KOSZYK='BasketLocalStore.basket',CK_LS_TS='BasketLocalStore.basketUpdateTimestamp';
function ckApi(u,o){return fetch(u,Object.assign({credentials:'same-origin',
  headers:{'Accept':'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'}},o||{}))
  .then(function(r){if(!r.ok)throw new Error('HTTP '+r.status+' '+u);return r.json();});}
function ckKoszykId(){
  /* storefront Shopera renderuje WYLACZNIE koszyk o tym id — musimy uzyc tego samego */
  try{var v=(localStorage.getItem(CK_LS_ID)||'').replace(/"/g,'');
    if(/^[a-f0-9]{16,}$/i.test(v))return v;}catch(e){}
  return null;
}
function ckZapewnijKoszyk(){
  var id=ckKoszykId();
  if(id)return Promise.resolve(id);
  return ckApi('/api/basket/',{method:'POST'}).then(function(j){
    var nid=j&&j.basket&&j.basket.id;
    if(!nid)throw new Error('brak id nowego koszyka');
    try{localStorage.setItem(CK_LS_ID,nid);localStorage.setItem(CK_LS_TS,String(Date.now()));}catch(e){}
    return nid;
  });
}
function ckDodajPozycje(bid,it){
  return ckApi('/api/basket/'+bid+'/item/'+it.s,{method:'POST',
    body:JSON.stringify({quantity:it.q||1,options:{},isExchangedWithLoyaltyPoints:false,bundledItems:[]})})
  .then(function(j){
    /* UWAGA: Shoper zwraca 200 nawet gdy produkt jest nieaktywny/wyprzedany — blad siedzi w flashMessages */
    var b=(j&&j.flashMessages||[]).filter(function(m){return m.isError;});
    if(b.length)throw new Error((it.n?it.n+': ':'')+b[0].message);
    return j;
  });
}
function dodajDoKoszyka(poz,btn){
  if(!poz||!poz.length)return;
  var stary=btn.textContent;
  btn.textContent='Dodaję…';btn.disabled=true;
  ckZapewnijKoszyk().then(function(bid){
    /* po kolei, nie rownolegle — Shoper serializuje operacje na koszyku */
    return poz.reduce(function(p,it){return p.then(function(){return ckDodajPozycje(bid,it);});},Promise.resolve());
  }).then(function(){
    /* bez tego storefront pokaze zapamietana (stara) zawartosc koszyka */
    try{localStorage.removeItem(CK_LS_KOSZYK);localStorage.setItem(CK_LS_TS,String(Date.now()));}catch(e){}
    btn.textContent='✓ Dodano — przechodzę do koszyka';
    ev('koszyk',{szt:poz.length});
    setTimeout(function(){location.href='/pl/basket';},800);
  }).catch(function(err){
    btn.textContent=stary;btn.disabled=false;
    if(window.console&&console.warn)console.warn('CK koszyk:',err&&err.message);
    /* komunikat inline z linkami — window.open padal na blokadach popupow */
    var ist=btn.parentNode.querySelector('.cart-err');if(ist)ist.remove();
    var d=document.createElement('div');d.className='cart-err';
    d.innerHTML='Nie udało się dodać do koszyka ('+((err&&err.message)||'błąd sieci')+'). Otwórz produkt i dodaj ręcznie: '
      +poz.map(function(it){return it.u?'<a href="https://czystakarma.pl'+it.u+'" target="_blank">'+(it.n||'produkt')+' →</a>':'';}).join(' ');
    btn.parentNode.insertBefore(d,btn.nextSibling);
  });
}
function bindBuy(){document.querySelectorAll('#ck a.btn-buy,#ck .mix-btn,#ck .smp-link a').forEach(function(a){a.addEventListener('click',function(){ev('buy',{u:a.getAttribute('href')});});});}
/* Dostępność: klikane divy dostają rolę przycisku, fokus z klawiatury i aktywację Enter/Spacją */
function a11y(){document.querySelectorAll('#ck .yn-opt,#ck .ak,#ck .age-card,#ck .forma-card,#ck .need,#ck .mcell,#ck .al-item,#ck .al-hd,#ck .pkg-tab').forEach(function(el){if(el.getAttribute('tabindex'))return;el.setAttribute('tabindex','0');el.setAttribute('role','button');el.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}});});}
